#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;using FileCompass.NetworkTransport;
namespace FileCompass {
 internal static class NewTextEditorTests {
  static bool Save(CodeEditorWindow window,bool saveAs=false){var task=window.Save(saveAs);NavigationTests.Wait(task);return task.Result;}
  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();CodeEditorWindow window=null;MainWindow main=null;
   Action<bool,string> check=(ok,text)=>{if(!ok)throw new Exception(text);checks.Add(text);File.WriteAllLines(Path.Combine(root,"progress.txt"),checks);};
   try{
    System.Threading.SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));L.ChangeLanguage("cs");FluentTheme.Ensure();AppearanceTheme.Apply("Light");
    window=new CodeEditorWindow(null){Left=-18000,Top=-18000,ShowActivated=false,ShowInTaskbar=false,WindowStartupLocation=WindowStartupLocation.Manual};window.Show();
    var doc=window.NewDocument(new EditorSaveLocation{Folder=root});check(doc.File.Path==null&&doc.Editor.Text==""&&doc.EncodingChoice==0&&doc.EolChoice==1&&!window.HasUnsaved,"new document is unnamed, blank, UTF-8 without BOM and Windows CRLF without creating a file");
    doc.Editor.Text="#!/bin/sh\r\necho 'Žluťoučký kůň'\r\n";window.Syntax.SelectedIndex=2;check(doc.Editor.SyntaxHighlighting!=null,"unnamed shell script has syntax highlighting before a filename is chosen");window.Syntax.SelectedIndex=3;check(doc.Editor.SyntaxHighlighting!=null,"RouterOS syntax is available before saving");
    string target=Path.Combine(root,"router-script.rsc");window.ChooseLocalPath=d=>target;check(Save(window)&&File.ReadAllBytes(target).SequenceEqual(new UTF8Encoding(false,true).GetBytes("#!/bin/sh\r\necho 'Žluťoučký kůň'\r\n")),"first save chooses filename and extension and writes exact UTF-8 CRLF bytes without BOM");
    check(doc.File.Path==target&&!window.HasUnsaved,"successful first save binds the name and clears dirty state");
    var combos=AdvancedToolsTests.Visual<ComboBox>(window).ToArray();var encoding=combos.Single(x=>x.Items.Count==6);var eol=combos.Single(x=>x.Items.Count==3);
    eol.SelectedIndex=2;check(Save(window)&&!File.ReadAllText(target).Contains("\r"),"LF remains an explicit selectable output format");eol.SelectedIndex=1;check(window.HasUnsaved&&doc.FormatModified,"changing only line endings is an unsaved document modification");check(Save(window)&&File.ReadAllText(target).Contains("\r\n"),"CRLF choice explicitly converts Linux line endings to Windows format");
    encoding.SelectedIndex=1;check(Save(window)&&File.ReadAllBytes(target).Take(3).SequenceEqual(new byte[]{239,187,191}),"UTF-8 BOM choice writes one explicit BOM");
    encoding.SelectedIndex=3;eol.SelectedIndex=2;check(Save(window)&&File.ReadAllBytes(target).SequenceEqual(Encoding.GetEncoding(1250).GetBytes("#!/bin/sh\necho 'Žluťoučký kůň'\n")),"Windows-1250 with LF is saved independently of the Windows host");
    byte[] old=File.ReadAllBytes(target);doc.Editor.Text="emoji 😀";encoding.SelectedIndex=4;check(!Save(window)&&File.ReadAllBytes(target).SequenceEqual(old)&&window.HasUnsaved,"unrepresentable characters reject saving without replacement characters or target damage");
    encoding.SelectedIndex=0;doc.Editor.Text="new\n";check(Save(window),"document remains saveable after encoding failure");
    string mixed=Path.Combine(root,"mixed.txt");File.WriteAllBytes(mixed,new UTF8Encoding(true).GetPreamble().Concat(new UTF8Encoding(false).GetBytes("one\r\ntwo\nthree\r")).ToArray());NavigationTests.Wait(window.OpenFile(mixed));var mixedDoc=window.Current;check(mixedDoc.File.Preamble.Length==3&&NewlineLabel(eol).Contains(L.Text("codeEditor.mixedEol")),"opened mixed endings and BOM are identified in original-format controls");
    byte[] original=File.ReadAllBytes(mixed);check(Save(window)&&File.ReadAllBytes(mixed).SequenceEqual(original),"Original preserves all mixed CRLF/LF/CR endings and UTF-8 BOM byte for byte");
    eol.SelectedIndex=2;window.Tabs.SelectedItem=doc.Tab;check(encoding.SelectedIndex==0&&eol.SelectedIndex==2,"tabs restore independent encoding and newline preferences");window.Tabs.SelectedItem=mixedDoc.Tab;check(eol.SelectedIndex==2&&mixedDoc.FormatModified,"pending format-only changes survive tab switches");check(Save(window),"format-only change can be saved");
    string foreign=Path.Combine(root,"external-change.txt");File.WriteAllText(foreign,"original");NavigationTests.Wait(window.OpenFile(foreign));window.Current.Editor.Text="editor";File.WriteAllText(foreign,"foreign");check(!Save(window)&&File.ReadAllText(foreign)=="foreign","editing retains the existing external-change overwrite guard");window.Current.Editor.IsModified=false;
    var blank=window.NewDocument(new EditorSaveLocation{Folder=root});window.ChooseLocalPath=d=>null;blank.Editor.Text="not saved";check(!Save(window)&&blank.File.Path==null&&window.HasUnsaved,"cancelling the name dialog retains the unnamed document and its text");blank.Editor.IsModified=false;
    var empty=window.NewDocument(new EditorSaveLocation{Folder=root});window.ChooseLocalPath=d=>Path.Combine(root,"empty-without-extension");check(Save(window)&&new FileInfo(empty.File.Path).Length==0&&Path.GetExtension(empty.File.Path)=="","saving an empty new document creates an empty file without forcing a .txt extension");
    window.Tabs.SelectedItem=doc.Tab;doc.Editor.Text=":local value 42\n:put $value\n";window.Width=800;window.Height=600;window.UpdateLayout();check(encoding.IsVisible&&eol.IsVisible&&window.Syntax.IsVisible&&eol.TranslatePoint(new Point(eol.ActualWidth,0),window).X<window.ActualWidth,"syntax/encoding/newline settings remain visible at compact width");NextStageTests.Draw(window,Path.Combine(root,"editor-linux-script.png"));
    foreach(var item in window.Documents){item.Editor.IsModified=false;item.FormatModified=false;}window.Close();window=null;

    string fixtureList=Path.Combine(root,"fixtures.txt");if(File.Exists(fixtureList))foreach(string line in File.ReadAllLines(fixtureList)){
     string[] parts=line.Split('|');var protocol=(NetworkProtocol)Enum.Parse(typeof(NetworkProtocol),parts[0]);int port=Int32.Parse(parts[1]);string serverRoot=parts[2];
     using(var browsing=new RemoteConnection(new NetworkProfile{Protocol=protocol,Host="127.0.0.1",Port=port,UserName="tester",Path="/",Name="Isolated "+protocol})){
      var options=browsing.Options("test-password");if(protocol!=NetworkProtocol.FTP){options.SshHostKeyFingerprint=browsing.Session.ScanFingerprint(options,"SHA-256");browsing.Profile.HostKeyFingerprint=options.SshHostKeyFingerprint;}browsing.Open(options);
      window=new CodeEditorWindow(null){Left=-18000,Top=-18000,ShowActivated=false,ShowInTaskbar=false,WindowStartupLocation=WindowStartupLocation.Manual};window.Show();var remote=window.NewDocument(new EditorSaveLocation{Folder="/sub",Remote=browsing.TransferConnection()});remote.Editor.Text=":local value 42\r\n:put $value\r\n";window.Syntax.SelectedIndex=3;window.ChooseRemoteName=d=>"router.rsc";
      check(Save(window)&&remote.RemotePath=="/sub/router.rsc"&&remote.File.Path==null,protocol+": unnamed document saves to its captured server/folder");
      string saved=Path.Combine(serverRoot,"sub","router.rsc");check(File.ReadAllBytes(saved).SequenceEqual(new UTF8Encoding(false).GetBytes(":local value 42\r\n:put $value\r\n")),protocol+": server receives exact UTF-8 Windows CRLF bytes");
      remote.Editor.Text=":put 43\n";check(Save(window)&&File.ReadAllText(saved)==":put 43\r\n",protocol+": subsequent Save updates the same remote file");
      File.WriteAllText(Path.Combine(serverRoot,"sub","occupied.rsc"),"keep");window.ChooseRemoteName=d=>"occupied.rsc";window.ConfirmRemoteOverwrite=p=>false;check(!Save(window,true)&&File.ReadAllText(Path.Combine(serverRoot,"sub","occupied.rsc"))=="keep"&&remote.RemotePath=="/sub/router.rsc",protocol+": refusing overwrite preserves both target and document binding");
      window.ConfirmRemoteOverwrite=p=>true;check(Save(window,true)&&remote.RemotePath=="/sub/occupied.rsc"&&File.ReadAllText(Path.Combine(serverRoot,"sub","occupied.rsc"))==":put 43\n",protocol+": confirmed Save as stages and commits the replacement");
      File.WriteAllText(Path.Combine(serverRoot,"sub","occupied.rsc"),"changed externally, longer");remote.Editor.Text=":put 99\n";check(!Save(window)&&File.ReadAllText(Path.Combine(serverRoot,"sub","occupied.rsc"))=="changed externally, longer"&&remote.Editor.IsModified,protocol+": foreign remote changes reject saving and retain unsaved text");
      check(!Directory.GetFiles(Path.Combine(serverRoot,"sub"),".FileCompass-*").Any(),protocol+": completed and rejected saves leave no staging files");
      var emptyRemote=window.NewDocument(remote.Location.Clone());window.ChooseRemoteName=d=>"empty-file";check(Save(window)&&new FileInfo(Path.Combine(serverRoot,"sub","empty-file")).Length==0,protocol+": empty extensionless new files upload correctly");
      var invalidName=window.NewDocument(remote.Location.Clone());window.ChooseRemoteName=d=>"../escape.txt";check(!Save(window)&&invalidName.RemotePath==null&&!File.Exists(Path.Combine(serverRoot,"escape.txt")),protocol+": invalid remote filenames cannot escape the captured folder");
      foreach(var item in window.Documents){item.Editor.IsModified=false;item.FormatModified=false;}window.Close();window=null;
     }
    }
    main=new MainWindow(root,new ProgramSettings{AutoRefresh=false}){Left=-18000,Top=-18000,ShowActivated=false,ShowInTaskbar=false,WindowStartupLocation=WindowStartupLocation.Manual};main.Show();NavigationTests.WaitPanels(main);var newButton=AdvancedToolsTests.Visual<Button>(main).Single(b=>Convert.ToString(b.Content)=="F2 "+L.Text("codeEditor.new"));newButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var opened=Application.Current.Windows.OfType<CodeEditorWindow>().Single();check(opened.Current.File.Path==null&&opened.Current.Location.Folder==root,"bottom F2 New file opens the internal editor with the current destination and no filename");var destinationPanel=FluentUiTests.Children<FilePanel>(main).First();string elsewhere=Directory.CreateDirectory(Path.Combine(root,"elsewhere")).FullName;destinationPanel.Navigate(elsewhere,false);NavigationTests.Wait(destinationPanel.NavigationTask);opened.Current.Editor.Text="#!/bin/sh\necho saved\n";
    Exception promptError=null;opened.Dispatcher.BeginInvoke(new Action(delegate{Window prompt=null;try{prompt=Application.Current.Windows.Cast<Window>().Single(w=>w.Owner==opened&&w.Title==L.Text("rename.fileNameLabel"));var inputs=AdvancedToolsTests.Visual<TextBox>(prompt).ToArray();check(inputs.Length==1,"local Save shows a single filename field in the application dialog");inputs[0].Text="captured-folder.sh";NextStageTests.Draw(prompt,Path.Combine(root,"filename-prompt.png"));AdvancedToolsTests.Visual<Button>(prompt).Single(b=>b.IsDefault).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}catch(Exception ex){promptError=ex;if(prompt!=null)prompt.Close();}}));
    check(Save(opened)&&promptError==null&&File.Exists(Path.Combine(root,"captured-folder.sh"))&&!File.Exists(Path.Combine(elsewhere,"captured-folder.sh")),"first Save prompts for name only and uses the captured folder after panel navigation");
    var collision=opened.NewDocument(new EditorSaveLocation{Folder=root});collision.Editor.Text="replacement";opened.ChooseLocalName=d=>"captured-folder.sh";opened.ConfirmLocalOverwrite=p=>false;check(!Save(opened)&&collision.File.Path==null&&File.ReadAllText(Path.Combine(root,"captured-folder.sh")).Contains("echo saved"),"refusing local overwrite retains original bytes and unnamed text");opened.ConfirmLocalOverwrite=p=>true;check(Save(opened)&&File.ReadAllText(Path.Combine(root,"captured-folder.sh"))=="replacement","confirmed local overwrite commits in the captured folder");
    var invalid=opened.NewDocument(new EditorSaveLocation{Folder=root});opened.ChooseLocalName=d=>"../escape.sh";check(!Save(opened)&&invalid.File.Path==null,"filename-only prompt rejects paths outside its folder");opened.ChooseLocalName=d=>null;check(!Save(opened)&&invalid.File.Path==null,"cancelling the filename-only prompt creates no file");
    opened.Close();main.RaiseEvent(new System.Windows.Input.KeyEventArgs(System.Windows.Input.Keyboard.PrimaryDevice,PresentationSource.FromVisual(main),0,System.Windows.Input.Key.F2){RoutedEvent=System.Windows.Input.Keyboard.PreviewKeyDownEvent});opened=Application.Current.Windows.OfType<CodeEditorWindow>().Single();check(opened.Current.File.Path==null,"F2 opens a new unnamed document instead of rename");opened.Close();NextStageTests.Draw(main,Path.Combine(root,"bottom-new-file.png"));main.Close();main=null;
    File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count+" checks"}));return 0;
   }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(window!=null){foreach(var item in window.Documents){item.Editor.IsModified=false;item.FormatModified=false;}window.Close();}if(main!=null)main.Close();}
  }
  static string NewlineLabel(ComboBox box){return Convert.ToString(box.Items[0]);}
 }
}
#endif
